svg.script:
const root = document.documentElement;
const palettes = {
  xbox: {
    a:'#107C10', b:'#E81123', x:'#0078D7', y:'#FFB900'
  },
  playstationClassic: {
    triangle:'#00A86B', circle:'#E83A4F', cross:'#2E7CF6', square:'#E95ACF'
  },
  playstationDualSense: {
    triangle:'#D8DCE5', circle:'#D8DCE5', cross:'#D8DCE5', square:'#D8DCE5'
  },
  nintendoSwitch: {
    a:'#F2F2F2', b:'#F2F2F2', x:'#F2F2F2', y:'#F2F2F2'
  }
};

function setVar(name, value){ if(value != null) root.style.setProperty(name, value); }
function setButton(options={}){
  if(options.symbol) root.setAttribute('data-symbol', String(options.symbol).toLowerCase());
  if(options.pressed != null) root.setAttribute('data-pressed', options.pressed ? 'true' : 'false');
  setVar('--button-fill', options.fill);
  setVar('--button-edge', options.edge);
  setVar('--symbol-color', options.symbolColor);
  setVar('--glow-color', options.glow);
  if(options.symbolStroke != null) setVar('--symbol-stroke', String(options.symbolStroke));
  if(options.scale != null) setVar('--button-scale', String(options.scale));
  return getButtonState();
}
function applyPalette(brand, symbol){
  const p = palettes[brand];
  const key = String(symbol || root.getAttribute('data-symbol')).toLowerCase();
  if(!p || !p[key]) return false;
  root.setAttribute('data-symbol', key);
  root.style.setProperty('--symbol-color', p[key]);
  return true;
}
function getButtonState(){
  const s=getComputedStyle(root);
  return {
    symbol:root.getAttribute('data-symbol'),
    pressed:root.getAttribute('data-pressed')==='true',
    fill:s.getPropertyValue('--button-fill').trim(),
    edge:s.getPropertyValue('--button-edge').trim(),
    symbolColor:s.getPropertyValue('--symbol-color').trim(),
    glow:s.getPropertyValue('--glow-color').trim()
  };
}
window.FaceButton = { set:setButton, palette:applyPalette, get:getButtonState, palettes };
addEventListener('message',e=>{
  if(!e.data || e.data.type!=='D5BT_FACE_BUTTON') return;
  if(e.data.palette) applyPalette(e.data.palette,e.data.symbol);
  setButton(e.data);
});
